mapper.select:
select count(*)
from lab
where id = #{labId}
  and department_id = #{departmentId}
  and deleted = 0

select count(distinct r.id)
from lab_reservation r
join lab l on l.id = r.lab_id
join lab_reservation_slot s on s.reservation_id = r.id
where l.deleted = 0
  and l.department_id = #{departmentId}
  and s.slot_status = 1
  and s.reservation_date between #{startDate} and #{endDate}

    and l.lab_type = #{labType}

select count(*)
from sys_user u
where u.deleted = 0
  and u.department_id = #{departmentId}
  and u.credit_score  <  #{lowCreditScore}

select count(distinct r.id)


    and r.lab_id = #{labId}


    and l.lab_type = #{labType}


    and r.status = #{status}


    and r.reservation_type = #{reservationType}

select count(distinct r.id)


    and r.lab_id = #{labId}


    and l.lab_type = #{labType}

and r.status = 1

    and r.reservation_type = #{reservationType}

select count(distinct r.id)


    and r.lab_id = #{labId}


    and l.lab_type = #{labType}

and r.status = 5

    and r.reservation_type = #{reservationType}

select date_format(s.reservation_date, '%Y-%m-%d') as name, count(distinct r.id) as value


    and r.lab_id = #{labId}


    and l.lab_type = #{labType}



        and r.status = #{status}


        and r.status in (2, 5)



    and r.reservation_type = #{reservationType}

group by date_format(s.reservation_date, '%Y-%m-%d')
order by name asc

select r.status as name, count(distinct r.id) as value


    and r.lab_id = #{labId}


    and l.lab_type = #{labType}


    and r.reservation_type = #{reservationType}

group by r.status

select r.reservation_type as name, count(distinct r.id) as value


    and r.lab_id = #{labId}


    and l.lab_type = #{labType}


    and r.status = #{status}

group by r.reservation_type

select case
         when exists (
           select 1 from sys_user_role ur
           join sys_role role on role.id = ur.role_id
           where ur.user_id = u.id and role.role_code in ('TEACHER', 'ROLE_TEACHER')
         ) then 'TEACHER'
         else 'STUDENT'
       end as name,
       count(distinct s.reservation_id) as value
from lab_reservation r
join lab l on l.id = r.lab_id
join sys_user u on u.id = r.applicant_user_id
join lab_reservation_slot s on s.reservation_id = r.id
where l.deleted = 0
  and l.department_id = #{departmentId}
  and s.slot_status = 1
  and s.reservation_date between #{startDate} and #{endDate}

    and r.lab_id = #{labId}


    and l.lab_type = #{labType}


    and r.status = #{status}


    and r.reservation_type = #{reservationType}

group by name

select coalesce(nullif(l.lab_type, ''), 'UNCLASSIFIED') as name,
       count(distinct r.id) as value


    and r.lab_id = #{labId}


    and l.lab_type = #{labType}


    and r.status = #{status}


    and r.reservation_type = #{reservationType}

group by coalesce(nullif(l.lab_type, ''), 'UNCLASSIFIED')
order by value desc, name asc

select l.id, l.lab_name as name, concat(l.building_name, l.room_no) as secondary, count(distinct s.reservation_id) as value from lab l left join lab_reservation r on r.lab_id = l.id and r.status in (2, 5) left join lab_reservation_slot s on s.reservation_id = r.id and s.slot_status = 1 and s.reservation_date between #{startDate} and #{endDate} where l.deleted = 0 and l.department_id = #{departmentId}
and l.id = #{labId}
and l.lab_type = #{labType}
group by l.id, l.lab_name, l.building_name, l.room_no order by value desc, l.id asc limit 10

select l.id, l.lab_name as name, concat(l.building_name, l.room_no) as secondary, count(distinct r.id) as value from lab l left join lab_reservation r on r.lab_id = l.id and r.status in (2, 5) left join lab_reservation_slot s on s.reservation_id = r.id and s.slot_status = 1 and s.reservation_date between #{startDate} and #{endDate} where l.deleted = 0 and l.department_id = #{departmentId}
and l.id = #{labId}
and l.lab_type = #{labType}
group by l.id, l.lab_name, l.building_name, l.room_no order by value asc, l.id asc limit 10

select p.period_name as name, count(*) as value from lab_reservation_slot s join lab_reservation r on r.id = s.reservation_id join lab l on l.id = r.lab_id join class_period p on p.id = s.period_id where l.deleted = 0 and l.department_id = #{departmentId} and r.status in (2, 5) and s.slot_status = 1 and s.reservation_date between #{startDate} and #{endDate}
and r.lab_id = #{labId}
and l.lab_type = #{labType}
group by p.id, p.period_name, p.sort_order, p.period_no order by p.sort_order asc, p.period_no asc

select count(*) from (
    select l.id, count(distinct s.reservation_id) as reservation_count
    from lab l
    left join lab_reservation r on r.lab_id = l.id and r.status in (2, 5)
    left join lab_reservation_slot s on s.reservation_id = r.id
        and s.slot_status = 1
        and s.reservation_date between #{startDate} and #{endDate}
    where l.deleted = 0
      and l.department_id = #{departmentId}

        and l.id = #{labId}


        and l.lab_type = #{labType}

    group by l.id
) summary
where summary.reservation_count > 0

select count(*) from (
    select l.id, count(distinct s.reservation_id) as reservation_count
    from lab l
    left join lab_reservation r on r.lab_id = l.id and r.status in (2, 5)
    left join lab_reservation_slot s on s.reservation_id = r.id
        and s.slot_status = 1
        and s.reservation_date between #{startDate} and #{endDate}
    where l.deleted = 0
      and l.department_id = #{departmentId}

        and l.id = #{labId}


        and l.lab_type = #{labType}

    group by l.id
) summary
where summary.reservation_count = 0

select count(*)
from lab_reservation_slot s
join lab_reservation r on r.id = s.reservation_id
join lab l on l.id = s.lab_id
where l.deleted = 0
  and l.department_id = #{departmentId}
  and r.status in (2, 5)
  and s.slot_status = 1
  and s.reservation_date between #{startDate} and #{endDate}

    and s.lab_id = #{labId}


    and l.lab_type = #{labType}

select coalesce(nullif(lab_type, ''), 'UNCLASSIFIED') as labType
from lab
where deleted = 0
  and department_id = #{departmentId}

    and id = #{labId}


    and lab_type = #{selectedLabType}

group by coalesce(nullif(lab_type, ''), 'UNCLASSIFIED')
order by labType asc

select count(*)
from lab_reservation_slot s
join lab_reservation r on r.id = s.reservation_id
join lab l on l.id = s.lab_id
where l.deleted = 0
  and l.department_id = #{departmentId}
  and coalesce(nullif(l.lab_type, ''), 'UNCLASSIFIED') = #{labType}
  and r.status in (2, 5)
  and s.slot_status = 1
  and s.reservation_date between #{startDate} and #{endDate}

    and s.lab_id = #{labId}

select os.weekday as weekday, count(*) as value
from lab_open_slot os
join lab l on l.id = os.lab_id
where l.deleted = 0
  and l.department_id = #{departmentId}
  and os.status = 1

    and os.lab_id = #{labId}


    and coalesce(nullif(l.lab_type, ''), 'UNCLASSIFIED') = #{labType}

group by os.weekday

select count(*)
from lab
where deleted = 0
  and department_id = #{departmentId}

    and id = #{labId}


    and coalesce(nullif(lab_type, ''), 'UNCLASSIFIED') = #{labType}

select count(*)
from lab_device d
join lab l on l.id = d.lab_id
where d.deleted = 0
  and l.deleted = 0
  and l.department_id = #{departmentId}

    and d.lab_id = #{labId}


    and l.lab_type = #{labType}

select count(*)
from lab_device d
join lab l on l.id = d.lab_id
where d.deleted = 0
  and l.deleted = 0
  and l.department_id = #{departmentId}
  and d.status = #{deviceStatus}

    and d.lab_id = #{labId}


    and l.lab_type = #{labType}

select count(*)
from lab_device_repair rr
join lab l on l.id = rr.lab_id
where l.deleted = 0
  and l.department_id = #{departmentId}
  and rr.created_at  >=  #{startDate}
  and rr.created_at  <  date_add(#{endDate}, interval 1 day)

    and rr.lab_id = #{labId}


    and l.lab_type = #{labType}

select l.id, l.lab_name as name, concat(l.building_name, l.room_no) as secondary, coalesce(sum(d.quantity), 0) as value from lab l left join lab_device d on d.lab_id = l.id and d.deleted = 0 where l.deleted = 0 and l.department_id = #{departmentId}
and l.id = #{labId}
and l.lab_type = #{labType}
group by l.id, l.lab_name, l.building_name, l.room_no order by value desc, l.id asc limit 12

select d.id, d.device_name as name, concat(l.lab_name, ' / ', d.device_code) as secondary, d.status as value from lab_device d join lab l on l.id = d.lab_id where d.deleted = 0 and l.deleted = 0 and l.department_id = #{departmentId} and d.status != 1
and d.lab_id = #{labId}
and l.lab_type = #{labType}
order by d.updated_at desc, d.id desc limit 10

select coalesce(nullif(d.brand, ''), 'OTHER_BRAND') as name, coalesce(sum(d.quantity), 0) as value from lab_device d join lab l on l.id = d.lab_id where d.deleted = 0 and l.deleted = 0 and l.department_id = #{departmentId}
and d.lab_id = #{labId}
and l.lab_type = #{labType}
group by coalesce(nullif(d.brand, ''), 'OTHER_BRAND') order by value desc, name asc limit 8

select date(rr.created_at) as name, count(*) as value
from lab_device_repair rr
join lab l on l.id = rr.lab_id
where l.deleted = 0
  and l.department_id = #{departmentId}
  and rr.created_at  >=  #{startDate}
  and rr.created_at  <  date_add(#{endDate}, interval 1 day)

    and rr.lab_id = #{labId}


    and l.lab_type = #{labType}

group by date(rr.created_at)
order by date(rr.created_at) asc

select count(*)
from lab_consumable c
join lab l on l.id = c.lab_id
where c.deleted = 0
  and l.deleted = 0
  and l.department_id = #{departmentId}

    and c.lab_id = #{labId}


    and l.lab_type = #{labType}

select count(*)
from lab_consumable c
join lab l on l.id = c.lab_id
where c.deleted = 0
  and l.deleted = 0
  and l.department_id = #{departmentId}
  and c.stock_quantity  <=  c.warning_threshold

    and c.lab_id = #{labId}


    and l.lab_type = #{labType}

select coalesce(sum(abs(log.change_amount)), 0)
from consumable_stock_log log
join lab_consumable c on c.id = log.consumable_id
join lab l on l.id = c.lab_id
where c.deleted = 0
  and l.deleted = 0
  and l.department_id = #{departmentId}
  and log.change_type = 'IN'
  and log.created_at  >=  #{startDate}
  and log.created_at  <  date_add(#{endDate}, interval 1 day)

    and c.lab_id = #{labId}


    and l.lab_type = #{labType}

select coalesce(sum(abs(log.change_amount)), 0)
from consumable_stock_log log
join lab_consumable c on c.id = log.consumable_id
join lab l on l.id = c.lab_id
where c.deleted = 0
  and l.deleted = 0
  and l.department_id = #{departmentId}
  and log.change_type = 'OUT'
  and log.created_at  >=  #{startDate}
  and log.created_at  <  date_add(#{endDate}, interval 1 day)

    and c.lab_id = #{labId}


    and l.lab_type = #{labType}

select c.id, c.consumable_name as name, concat(l.lab_name, ' / ', c.unit) as secondary, coalesce(sum(abs(log.change_amount)), 0) as value from lab_consumable c join lab l on l.id = c.lab_id left join consumable_stock_log log on log.consumable_id = c.id and log.change_type = 'OUT' and log.created_at >= #{startDate} and log.created_at < date_add(#{endDate}, interval 1 day) where c.deleted = 0 and l.deleted = 0 and l.department_id = #{departmentId}
and c.lab_id = #{labId}
and l.lab_type = #{labType}
group by c.id, c.consumable_name, l.lab_name, c.unit order by value desc, c.id asc limit 10

select c.id, c.consumable_name as name, concat(l.lab_name, ' / warning:', c.warning_threshold, c.unit) as secondary, c.stock_quantity as value from lab_consumable c join lab l on l.id = c.lab_id where c.deleted = 0 and l.deleted = 0 and l.department_id = #{departmentId} and c.stock_quantity <= c.warning_threshold
and c.lab_id = #{labId}
and l.lab_type = #{labType}
order by c.stock_quantity asc, c.id asc limit 10

select date_format(log.created_at, '%Y-%m-%d') as name, coalesce(sum(abs(log.change_amount)), 0) as value from consumable_stock_log log join lab_consumable c on c.id = log.consumable_id join lab l on l.id = c.lab_id where c.deleted = 0 and l.deleted = 0 and l.department_id = #{departmentId} and log.change_type = 'IN' and log.created_at >= #{startDate} and log.created_at < date_add(#{endDate}, interval 1 day)
and c.lab_id = #{labId}
and l.lab_type = #{labType}
group by date_format(log.created_at, '%Y-%m-%d') order by name asc

select date_format(log.created_at, '%Y-%m-%d') as name, coalesce(sum(abs(log.change_amount)), 0) as value from consumable_stock_log log join lab_consumable c on c.id = log.consumable_id join lab l on l.id = c.lab_id where c.deleted = 0 and l.deleted = 0 and l.department_id = #{departmentId} and log.change_type = 'OUT' and log.created_at >= #{startDate} and log.created_at < date_add(#{endDate}, interval 1 day)
and c.lab_id = #{labId}
and l.lab_type = #{labType}
group by date_format(log.created_at, '%Y-%m-%d') order by name asc

select l.id, l.lab_name as name, coalesce(nullif(l.lab_type, ''), 'UNCLASSIFIED') as secondary, coalesce(sum(abs(log.change_amount)), 0) as value from lab l left join lab_consumable c on c.lab_id = l.id and c.deleted = 0 left join consumable_stock_log log on log.consumable_id = c.id and log.change_type = 'OUT' and log.created_at >= #{startDate} and log.created_at < date_add(#{endDate}, interval 1 day) where l.deleted = 0 and l.department_id = #{departmentId}
and l.id = #{labId}
and l.lab_type = #{labType}
group by l.id, l.lab_name, l.lab_type order by value desc, l.id asc limit 10
